/** The locale name for Intl (dates, times, numbers) and for speech recognition. */
export const intlLocale = (lang: string) => (lang === 'tl' ? 'fil' : lang);
export const speechLocale = (lang: string) => ({ ar: 'ar-SA', en: 'en-US', ur: 'ur-PK', hi: 'hi-IN', tl: 'fil-PH', fr: 'fr-FR', ml: 'ml-IN', bn: 'bn-BD', fa: 'fa-IR', tr: 'tr-TR', es: 'es-ES', ru: 'ru-RU', zh: 'zh-CN', de: 'de-DE', it: 'it-IT', pt: 'pt-BR', nl: 'nl-NL', pl: 'pl-PL', uk: 'uk-UA', el: 'el-GR', sv: 'sv-SE' } as Record<string, string>)[lang] ?? 'en-US';
/** Put a flat pack ("a.b": "text", "list[2]": "text") over a copy of the English dictionary: whatever the pack lacks stays English. */
export function overlay<T>(base: T, flat: Record<string, string>): T {
  const out: any = structuredClone(base);
  for (const [path, text] of Object.entries(flat)) {
    if (typeof text !== 'string' || !text) continue;
    const parts = path.replace(/\[(\d+)\]/g, '.$1').split('.');
    let node = out;
    for (let i = 0; i < parts.length - 1 && node != null; i++) node = node[parts[i]];
    const last = parts[parts.length - 1];
    if (node != null && typeof node === 'object' && last in node && typeof node[last] === 'string') node[last] = text;   // only an existing text is replaced: a pack can never add or change structure
  }
  return out;
}

/** Like WhatsApp: the person's saved choice wins; otherwise the device language (the first language in the device's list that we speak); otherwise English.
 *  Anyone can change it later in «أنت ← المظهر». Languages we have no dictionary for yet fall back to English until one is added to SUPPORTED. */
export function pickLang(saved: string | null | undefined, deviceLanguages: readonly string[]): Lang {
  if (saved && (SUPPORTED as string[]).includes(saved)) return saved as Lang;
  for (const l of deviceLanguages) { let base = l.toLowerCase().split('-')[0]; if (base === 'fil') base = 'tl'; if ((SUPPORTED as string[]).includes(base)) return base as Lang; }
  return 'en';
}
function detectLang(): Lang {
  let saved: string | null = null;
  try { saved = localStorage.getItem('lang'); } catch { /* private mode */ }
  const device = typeof navigator !== 'undefined' ? (navigator.languages?.length ? navigator.languages : [navigator.language ?? '']) : [];
  return pickLang(saved, device);
}

/** A chat notice stored as "sys:{k,a}" becomes words in the reader's language; an older one (stored as Arabic words) is shown as it was. */
export function systemText(body: string, t: { sys: Record<string, string> }): string {
  if (!body.startsWith('sys:')) return body;
  try {
    const { k, a } = JSON.parse(body.slice(4)) as { k: string; a: Record<string, string | number> };
    const tpl = t.sys[k];
    if (!tpl) return '';
    const vals: Record<string, string | number> = { ...a };
    if (a.n !== undefined && a.u) vals.wait = t.sys[a.u === 'h' ? 'waitH' : 'waitD'].replace('{n}', String(a.n));
    return tpl.replace(/\{(\w+)\}/g, (_, n) => String(vals[n] ?? ''));
  } catch { return ''; }
}

