type Dict = typeof dict.ar;
const Ctx = createContext<{ lang: Lang; t: Dict; setLang: (l: Lang) => void; machine: boolean }>(null as never);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(detectLang);
  const [pack, setPack] = useState<{ lang: Lang; t: Dict } | null>(null);
  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dir = LANG_INFO[lang].rtl ? 'rtl' : 'ltr';
    if (lang === 'ar' || lang === 'en') { setPack(null); return; }
    let cancelled = false;
    PACKS[lang]().then(m => { if (!cancelled) setPack({ lang, t: overlay(dict.en as Dict, m.default) }); }).catch(() => { /* offline: English stays */ });
    return () => { cancelled = true; };
  }, [lang]);
  const setLang = (l: Lang) => { setLangState(l); try { localStorage.setItem('lang', l); } catch { /* private mode */ } };
  const t = (lang === 'ar' || lang === 'en' ? dict[lang] : pack?.lang === lang ? pack.t : dict.en) as Dict;
  return <Ctx.Provider value={{ lang, t, setLang, machine: LANG_INFO[lang].machine }}>{children}</Ctx.Provider>;
}

export const useI18n = () => useContext(Ctx);
